{{#if mcp_servers}}{
  "mcpServers": {
{{#each mcp_servers}}    "{{slug}}": {{#if local}}{
      "type": "stdio",
      "command": "{{command}}",
      "args": [{{#each args}}"{{value}}"{{#unless @last}}, {{/unless}}{{/each}}]{{#if env}},
      "env": { {{#each env}}"{{name}}": "{{value}}"{{#unless @last}}, {{/unless}}{{/each}} }{{/if}}
    }{{else}}{
      "type": "http",
      "url": "{{#if (and forward_auth (not ../forward_auth))}}{{fwd_prefix}}${STREAMSCOPE_MCP_KEY}/mcp/{{slug}}{{else}}{{url}}{{/if}}"{{#if headers}},
      "headers": { {{#each headers}}"{{name}}": "{{#if (and (eq name "Authorization") (not (or ../forward_auth ../../forward_auth)))}}Bearer ${STREAMSCOPE_MCP_KEY}{{else}}{{value}}{{/if}}"{{#unless @last}}, {{/unless}}{{/each}} }{{/if}}
    }{{/if}}{{#unless @last}},{{/unless}}
{{/each}}  }
}
{{/if}}

