{
  "env": {
    "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC": "1",
    "ANTHROPIC_BASE_URL": "{{base_url}}"{{#unless forward_auth}},
    "ANTHROPIC_AUTH_TOKEN": "{{api_key}}",
    "ANTHROPIC_MODEL": "{{model_alias}}",
    "ANTHROPIC_DEFAULT_SONNET_MODEL": "{{model_slot_default}}",
    "ANTHROPIC_DEFAULT_OPUS_MODEL": "{{model_slot_plan}}",
    "ANTHROPIC_DEFAULT_HAIKU_MODEL": "{{model_slot_fast}}"{{/unless}}{{#each mcp_servers}}{{#if @first}}{{#unless local}}{{#unless ../forward_auth}},
    "STREAMSCOPE_MCP_KEY": "{{api_key}}"{{/unless}}{{/unless}}{{/if}}{{/each}}
  }{{#if project_scope}}{{#if mcp_servers}},
  "enabledMcpjsonServers": [{{#each mcp_servers}}"{{slug}}"{{#unless @last}}, {{/unless}}{{/each}}]{{/if}}{{/if}}
}

